<?php
namespace App\Filament\Admin\Resources\Invitations\Pages;
use App\Application\Identity\InvitationService;use App\Filament\Admin\Concerns\NotifiesServiceValidationErrors;use App\Filament\Admin\Resources\Invitations\InvitationResource;use App\Models\Tenant;use Illuminate\Database\Eloquent\Model;use Filament\Notifications\Notification;use Filament\Resources\Pages\CreateRecord;
final class CreateInvitation extends CreateRecord{use NotifiesServiceValidationErrors;protected static string$resource=InvitationResource::class;protected function handleRecordCreation(array$data):Model{/* P4: /insurer pins tenant and carrier to the caller's own, whatever the browser sent. */if(InvitationResource::inPortal()){$data['tenant_id']=app(\App\Domain\Tenancy\TenantContext::class)->id();$data['carrier_id']=\App\Application\WebExperiences\PortalScope::carrierId();if(!in_array($data['role_code']??null,\App\Application\WebExperiences\PortalAccess::roles('insurer'),true)){throw\Illuminate\Validation\ValidationException::withMessages(['data.role_code'=>__('insurer_portal_ops.staff.role_not_allowed')]);}}$result=app(InvitationService::class)->issue(Tenant::findOrFail($data['tenant_id']),auth()->user(),$data['recipient_email']??null,$data['recipient_phone_e164']??null,$data['role_code'],(int)$data['ttl_hours'],$data['carrier_id']??null);Notification::make()->title('Invitation created')->body('One-time token: '.$result['token'])->warning()->persistent()->send();return$result['invitation'];}}
